// ═══ FAILURE 1: COMPOUND ACTION (counter++) ═══
volatile int txnCount = 0;

// Thread-1: read(0) → +1 → write(1)
// Thread-2: read(0) → +1 → write(1) ← LOST!
// volatile ensures Thread-2 SEES the latest value for each read
// but between Thread-1's read and write, Thread-2 also reads the old value!
// FIX: AtomicInteger txnCount = new AtomicInteger(0);
//      txnCount.incrementAndGet(); → CAS: atomic read-modify-write!

// ═══ FAILURE 2: CHECK-THEN-ACT ═══
volatile int balance = 100000;

void withdraw(int amount) {
    if (balance >= amount) {    // Thread-1: reads 100000 (volatile read (Recommended) )
        // Thread-2 also reads 100000 HERE (volatile read (Recommended) )
        balance -= amount;       // Thread-1: writes 40000 (volatile write (Recommended) )
        // Thread-2: writes 40000 (or -20000!) — stale check!
    }
}
// volatile ensures each read/write is fresh
// but the GAP between if-check and subtraction is NOT protected!
// FIX: synchronized void withdraw(int amount) { if(balance>=amount) balance-=amount; }

// ═══ FAILURE 3: MULTI-VARIABLE INVARIANT ═══
volatile int low = 0;   // invariant: low <= high
volatile int high = 10;

void updateRange(int newLow, int newHigh) {
    low = newLow;    // Thread-1: sets low = 8
    // ANOTHER THREAD READS HERE: low=8, high=5 → INVARIANT VIOLATED!
    high = newHigh;  // Thread-1: sets high = 12
}
// Even though both are volatile, updating TWO variables is NOT atomic!
// Between the two writes, another thread sees an inconsistent state.
// FIX: synchronized updateRange() { low = newLow; high = newHigh; }
// Or: use an immutable Range record: volatile Range range;
//     range = new Range(newLow, newHigh); → single volatile write!

// ═══ WHEN volatile IS sufficient ═══
// (Recommended) Single flag: volatile boolean running = true;
// (Recommended) One writer, many readers: volatile BigDecimal latestPrice;
// (Recommended) Immutable object reference: volatile Config config = new Config(...);
//    (single write of reference, object itself is immutable)
