package com.bank.volatilefail;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class VolatileFailuresTest {

    // ═══ FAILURE 1: volatile counter++ loses increments ═══
    @Test
    void volatileCounter_losesIncrements() throws InterruptedException {
        int[] counter = {0};  // simulates volatile (test limitation)
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < 1000; j++) counter[0]++;
                latch.countDown();
            }).start();
        }
        latch.await();
        System.out.println("volatile counter: " + counter[0] + " (expected 100000)");
        // Likely < 100000 — lost increments!
    }

    // ═══ FIX 1: AtomicInteger ═══
    @Test
    void atomicCounter_noLoss() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < 1000; j++) counter.incrementAndGet();
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(counter.get()).isEqualTo(100000);  // exact!
    }

    // ═══ FAILURE 2: volatile check-then-act (overdraft) ═══
    @Test
    void volatileCheckThenAct_overdraft() throws InterruptedException {
        int[] balance = {100};
        int overdrafts = 0;

        for (int trial = 0; trial < 100; trial++) {
            balance[0] = 100;
            CountDownLatch latch = new CountDownLatch(2);

            for (int t = 0; t < 2; t++) {
                new Thread(() -> {
                    if (balance[0] >= 70) {
                        try { Thread.sleep(1); } catch (InterruptedException e) { }
                        balance[0] -= 70;
                    }
                    latch.countDown();
                }).start();
            }
            latch.await();
            if (balance[0] < 0) overdrafts++;
        }
        System.out.println("Overdrafts: " + overdrafts + "/100 trials");
    }

    // ═══ FIX 2: synchronized check-then-act ═══
    static class SafeAccount {
        int balance;
        SafeAccount(int b) { balance = b; }
        synchronized boolean withdraw(int amount) {
            if (balance >= amount) { balance -= amount; return true; }
            return false;
        }
    }

    @Test
    void synchronizedCheckThenAct_noOverdraft() throws InterruptedException {
        for (int trial = 0; trial < 100; trial++) {
            SafeAccount acc = new SafeAccount(100);
            CountDownLatch latch = new CountDownLatch(2);
            new Thread(() -> { acc.withdraw(70); latch.countDown(); }).start();
            new Thread(() -> { acc.withdraw(70); latch.countDown(); }).start();
            latch.await();
            assertThat(acc.balance).isGreaterThanOrEqualTo(0);  // NEVER negative!
        }
    }

    // ═══ FAILURE 3: multi-variable invariant ═══
    // ═══ FIX: immutable record + volatile reference ═══
    record PriceRange(int bid, int ask) {
        PriceRange { if (bid > ask) throw new IllegalArgumentException("bid > ask!"); }
    }

    @Test
    void immutableRecord_atomicReferenceUpdate() {
        AtomicReference<PriceRange> priceRef = new AtomicReference<>(new PriceRange(100, 105));

        // Single atomic update — both bid and ask change together!
        priceRef.set(new PriceRange(102, 107));

        PriceRange current = priceRef.get();
        assertThat(current.bid()).isLessThanOrEqualTo(current.ask());  // invariant holds!
    }
}
